css:
.fx-bdy{width:min(560px,100%);display:grid;grid-template-columns:200px 1fr;gap:2em;align-items:center}
.fx-bdy svg{width:100%;height:auto}
.fx-bdy .z{fill:color-mix(in srgb,var(--primary) 12%,var(--surface));stroke:var(--primary);stroke-width:1.5;cursor:pointer;transition:fill calc(.2s/var(--speed))}
.fx-bdy .z:hover{fill:color-mix(in srgb,var(--accent) 35%,var(--surface))}
.fx-bdy .z:focus-visible{outline:none;stroke:var(--accent);stroke-width:3}
.fx-bdy .z.on{fill:var(--accent)}
.fx-bdy h3{font-size:1.2em;margin-bottom:.6em}
.fx-bdy ul{list-style:none;padding:0;margin:0;min-height:8em;display:grid;gap:.4em;align-content:start}
.fx-bdy li{display:flex;justify-content:space-between;padding:.5em .8em;border-radius:calc(var(--radius)*.6);background:color-mix(in srgb,var(--accent) 14%,var(--surface));font-weight:600;font-size:.92em}
.fx-bdy .empty{opacity:.55;background:none;font-weight:400}
@media(max-width:540px){.fx-bdy{grid-template-columns:1fr}.fx-bdy svg{max-width:200px;margin:auto}}
@media(prefers-reduced-motion:reduce){.fx-bdy .z{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-bdy .z.is-tap{fill:color-mix(in srgb,var(--accent) 35%,var(--surface))}

js:
(function(){var r=document.querySelector('.fx-bdy'),zs=r.querySelectorAll('.z'),l=r.querySelector('#fx-bdy-l'),on={};
function draw(){var k=Object.keys(on).filter(function(x){return on[x]});l.innerHTML=k.length?k.map(function(x){return '<li>'+x+'<span>✓</span></li>'}).join(''):'<li class="empty">Tap an area on the figure</li>';
zs.forEach(function(z){var a=!!on[z.dataset.n];z.classList.toggle('on',a);z.setAttribute('aria-pressed',a)})}
function tog(z){on[z.dataset.n]=!on[z.dataset.n];draw()}
zs.forEach(function(z){z.onclick=function(){tog(z)};z.onkeydown=function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();tog(z)}}});draw()})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
